import 'package:flutter/material.dart';
import 'package:package_info_plus/package_info_plus.dart';

class AppInfoPage extends StatefulWidget {
  const AppInfoPage({super.key});

  @override
  State<AppInfoPage> createState() => _AppInfoPageState();
}

class _AppInfoPageState extends State<AppInfoPage> {
  PackageInfo? _info;

  @override
  void initState() {
    super.initState();
    PackageInfo.fromPlatform().then((value) => setState(() => _info = value));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('앱 정보')),
      body: _info == null
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              children: [
                ListTile(title: const Text('앱 이름'), subtitle: Text(_info!.appName)),
                ListTile(title: const Text('패키지명'), subtitle: Text(_info!.packageName)),
                ListTile(title: const Text('버전'), subtitle: Text(_info!.version)),
                ListTile(title: const Text('빌드 번호'), subtitle: Text(_info!.buildNumber)),
              ],
            ),
    );
  }
}

Future<bool> needsUpdate(String latestVersion) async {
  final info = await PackageInfo.fromPlatform();
  final current = info.version.split('.').map(int.parse).toList();
  final latest = latestVersion.split('.').map(int.parse).toList();
  for (int i = 0; i < 3; i++) {
    if (latest[i] > current[i]) return true;
    if (latest[i] < current[i]) return false;
  }
  return false;
}

Future<Map<String, dynamic>> buildReport(Object error) async {
  final info = await PackageInfo.fromPlatform();
  return {
    'error': error.toString(),
    'appName': info.appName,
    'version': info.version,
    'buildNumber': info.buildNumber,
  };
}
